module string_validator(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input [7:0] char_array [0:15],\n    input [4:0] str_len,\n    output reg result,\n    output reg done\n);\n    \n    // Main FSM states\n    localparam [1:0] IDLE      = 2'd0;\n    localparam [1:0] PROC      = 2'd1;\n    localparam [1:0] FINISH    = 2'd2;\n    \n    // Character sequence states\n    localparam [1:0] STATE_A   = 2'd0;\n    localparam [1:0] STATE_B   = 2'd1;\n    localparam [1:0] STATE_C   = 2'd2;\n    \n    reg [1:0] main_state, next_main_state;\n    reg [1:0] curr_char_state, next_char_state;\n    reg [4:0] index;\n    reg [4:0] count_a, count_b, count_c;\n    reg error_flag;\n    reg [4:0] cycle_count;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            main_state      <= IDLE;\n            curr_char_state <= STATE_A;\n            index           <= 5'd0;\n            count_a         <= 5'd0;\n            count_b         <= 5'd0;\n            count_c         <= 5'd0;\n            error_flag      <= 1'b0;\n            done            <= 1'b0;\n            result          <= 1'b0;\n            cycle_count     <= 5'd0;\n        end else begin\n            main_state      <= next_main_state;\n            curr_char_state <= next_char_state;\n            \n            if (main_state == IDLE) begin\n                cycle_count <= 5'd0;\n            end else begin\n                cycle_count <= cycle_count + 5'd1;\n            end\n            \n            case (main_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 1'b0;\n                    if (start) begin\n                        index       <= 5'd0;\n                        count_a     <= 5'd0;\n                        count_b     <= 5'd0;\n                        count_c     <= 5'd0;\n                        error_flag  <= 1'b0;\n                        curr_char_state <= STATE_A;\n                    end\n                end\n                \n                PROC: begin\n                    if (index < str_len) begin\n                        case (curr_char_state)\n                            STATE_A: begin\n                                if (char_array[index] == 8'h61) begin\n                                    count_a <= count_a + 5'd1;\n                                end else if (char_array[index] == 8'h62) begin\n                                    count_b <= count_b + 5'd1;\n                                    next_char_state <= STATE_B;\n                                end else begin\n                                    error_flag <= 1'b1;\n                                end\n                            end\n                            \n                            STATE_B: begin\n                                if (char_array[index] == 8'h62) begin\n                                    count_b <= count_b + 5'd1;\n                                end else if (char_array[index] == 8'h63) begin\n                                    count_c <= count_c + 5'd1;\n                                    next_char_state <= STATE_C;\n                                end else begin\n                                    error_flag <= 1'b1;\n                                end\n                            end\n                            \n                            STATE_C: begin\n                                if (char_array[index] == 8'h63) begin\n                                    count_c <= count_c + 5'd1;\n                                end else begin\n                                    error_flag <= 1'b1;\n                                end\n                            end\n                            \n                            default: error_flag <= 1'b1;\n                        endcase\n                        index <= index + 5'd1;\n                    end\n                    \n                    // Cycle limit safety check\n                    if (cycle_count >= 5'd20) error_flag <= 1'b1;\n                end\n                \n                FINISH: begin\n                    result <= (count_a >= 5'd1) && \n                              (count_b >= 5'd1) && \n                              ((count_c == count_a) || (count_c == count_b)) && \n                              !error_flag;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n    \n    // Combinational next state logic\n    always @(*) begin\n        next_main_state = main_state;\n        next_char_state = curr_char_state;\n        \n        case (main_state)\n            IDLE: begin\n                if (start) next_main_state = PROC;\n            end\n            \n            PROC: begin\n                if (index >= str_len) begin\n                    next_main_state = FINISH;\n                end else if (cycle_count >= 5'd20) begin\n                    next_main_state = FINISH;\n                end\n            end\n            \n            FINISH: begin\n                next_main_state = IDLE;\n            end\n            \n            default: next_main_state = IDLE;\n        endcase\n    end\nendmodule